import React, { useState } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import './Tabs.css';

const Tabs = () => {
  const [activeTab, setActiveTab] = useState(0);

  const tabs = [
    { title: 'Tips', icon: 'M12,2A10,10 0 0,1 22,12A10,10 0 0,1 12,22A10,10 0 0,1 2,12A10,10 0 0,1 12,2M11,17H13V11H11V17Z', component: Tips },
    { title: 'Employees', icon: 'M16,13C15.71,13 15.38,13 15.03,13.05C16.19,13.89 17,15 17,16.5V19H23V16.5C23,14.17 18.33,13 16,13M8,13C5.67,13 1,14.17 1,16.5V19H15V16.5C15,14.17 10.33,13 8,13M8,11A3,3 0 0,0 11,8A3,3 0 0,0 8,5A3,3 0 0,0 5,8A3,3 0 0,0 8,11M16,11A3,3 0 0,0 19,8A3,3 0 0,0 16,5A3,3 0 0,0 13,8A3,3 0 0,0 16,11Z', component: Employees },
    { title: 'Summary', icon: 'M14,10H2V12H14V10M14,6H2V8H14V6M2,16H10V14H2V16M21.5,11.5L23,13L16,20L11.5,15.5L13,14L16,17L21.5,11.5Z', component: Summary },
  ];

  return (
    <div className="tabs">
      <ul>
        {tabs.map((tab, index) => (
          <li key={index} title={tab.title}>
            <button onClick={() => setActiveTab(index)} role="button">
              <svg viewBox="0 0 24 24">
                <path d={tab.icon} />
              </svg>
              <br />
              <span>{tab.title}</span>
            </button>
          </li>
        ))}
      </ul>

      <div className="slider">
        <div
          className="indicator"
          style={{ transform: `translateX(${activeTab * 100}%)` }}
        ></div>
      </div>

      <div className="content">
        {tabs.map((tab, index) => (
          <section key={index} style={{ display: index === activeTab ? 'block' : 'none' }}>
            <h2>{tab.title}</h2>
            {tab.component ? <tab.component /> : <p>{tab.content}</p>}
          </section>
        ))}
      </div>
    </div>
  );
};

export default Tabs;
